#!/usr/bin/env bash
# Titres fluides au laboratoire de rendu + chapitre « Le constructeur de pages » :
#   - h1 à h3 se règlent par leurs bornes (téléphone / grand écran) au lieu d'une taille fixe ;
#     un réglage déjà enregistré pour ces titres est ignoré : refaire « Appliquer au site » ;
#   - nouveau chapitre 5.1 (partie Contenu éditorial) et raccords.
# Prérequis : apply-styles.sh.
# Usage (racine du repo) : bash apply-titres-constructeur.sh
set -euo pipefail
cd "$(dirname "$0")"
[ -f pnpm-workspace.yaml ] || { echo "À lancer à la racine du repo."; exit 1; }

if git show HEAD:"apps/web/content/docs/dev/contenu/constructeur-de-pages.mdx" 2>/dev/null | grep -qF "title: \"Le constructeur de pages\""; then echo "Déjà appliqué (commité)."; exit 0; fi
grep -qF "title: \"Les styles\"" "apps/web/content/docs/dev/front/styles.mdx" 2>/dev/null || { echo "❌ lancer d'abord apply-styles.sh"; exit 1; }
MODIFIED=("apps/web/content/docs/dev/front/styles.mdx" "apps/web/content/docs/dev/index.mdx" "apps/web/content/docs/dev/stockage/le-finder.mdx" "apps/web/src/app/globals.css" "apps/web/src/features/design-lab/BlockStyleLab.tsx" "apps/web/src/features/page-builder/PageRenderer.tsx" "packages/contracts/src/page/README.md")
CREATED=("apps/web/content/docs/dev/contenu/constructeur-de-pages.mdx")
restore(){ git checkout -q -- "${MODIFIED[@]}" 2>/dev/null || true; rm -f "${CREATED[@]}"; rmdir -p "apps/web/content/docs/dev/contenu" 2>/dev/null || true; echo "  ↩ fichiers restaurés"; }
if grep -qF "title: \"Le constructeur de pages\"" "apps/web/content/docs/dev/contenu/constructeur-de-pages.mdx" 2>/dev/null; then echo "  restes d'un essai précédent non commité → nettoyage"; restore; fi
trap 'restore' ERR

mkdir -p "apps/web/content/docs/dev/contenu"
